using System.ComponentModel;
using System.Text.Json;
using System.Text.Json.Nodes;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;
using TiaMcp.Core;

namespace TiaMcp.Host;

[McpServerToolType]
public sealed class HmiComponentTools(HostOptions options)
{
    [McpServerTool(Name = "hmi_text_list_generate_set", ReadOnly = false, Destructive = false, OpenWorld = false)]
    [Description("Generate or reopen retained offline Unified text-list sets from a revalidated v7 review; exactly one committed request uploadRef or retained recordId. v1 retains fixed-identity coordinated Bool/integer child authors. v2 requires an exact previous v1/v2 set and explicit add/update/rename output rows, previousOutputId, listName, bindingAction preserve/rebind, removeOutputIds and unchanged retainOutputIds. Every predecessor and current declared output/binding is accounted for. Complete baseline/current pairs must equal exact predecessor bytes; optional supplied proposed pairs must match derived candidates. Same-type rebinding requires exact before lineage and captured after declarations. Explicit unified-text-list-set-request.v3 permits integer-value-preserving.v1 typeConversion with fromType/toType for fixed-identity numeric updates among SInt/USInt/Int/UInt/DInt/UDInt. Original state intervals, translations and current files must remain exact and every listed value must fit both captured types. Overflow and unrelated conflicts refuse; this generates offline text-list candidates and never converts PLC values. V3 predecessors require explicit v3 evolution; no implicit conversion. Renames, swaps and removals are destructive-effect previews only, never file/native operations. Any conflict suppresses all published candidates. v2 retains its own output/transition lineage, preserving v1 and original author records. Reopen revalidates all original sources, predecessor sets/authors, candidates and selected peer bytes. 0..16 surviving v2 outputs, 32 candidate/peer files, 64 MiB bytes, 4 MiB input, 16 MiB record, depth 16, 128 MiB lineage input and shared 512 MiB retention. Final immutable record is completion; interruption may leave orphan immutable artifacts. Download references with artifact_read. No native/TIA/runtime access, ownership, complete project/dependency coverage or preservation qualification.")]
    public CallToolResult GenerateTextListSet(string? uploadRef = null, string? recordId = null) => Run(store => store.GenerateTextListSet(uploadRef, recordId));

    [McpServerTool(Name = "hmi_text_list_author", ReadOnly = false, Destructive = false, OpenWorld = false)]
    [Description("Author downloadable plain Unified text-list configuration and TextLibrary YAML candidates from a committed unified-text-list-author-request.v1/v2/v3 uploadRef, or reopen/revalidate a retained authoring recordId; supply exactly one. v2 profile unified-bool-binding-text-list.v1 derives one Bool list from an exact revalidated v7 Unified hmiResource output and component binding, with explicit languages and False/True translations. v3 profile unified-integer-state-text-list.v1 supports exact captured SInt/USInt/Int/UInt/DInt/UDInt/LInt types with 1..256 explicit disjoint SingleValue/Range states and translations. Missing value coverage and original selected dependency associations stay explicit; requireFullTypeCoverage blocks candidates with gaps. State additions/removals/relabels are supported; output/list/library/file renames and implicit type conversion are refused. Regeneration requires a previous author record and matching independent baseline/current candidate pairs; relevant conflicts suppress both candidates. Explicit retainOutputIds preserve selected peer bytes. Reopen checks original reviews, previous candidates and output bytes; predecessor depth 16 and lineage input budget 128 MiB. Explicit languages/default, text translations, list entries and references are required. Supports Decimal SingleValue/Range/From/To and nonnegative SingleValue BitNumber/Bool (Bool 0 or 1); overlaps, duplicate names, missing/unused translations and ambiguous references refuse. Signed 64-bit integer encoding is not native numeric-range certification. Bounds: 4 MiB request, 128 lists, 4096 total entries/texts, 32 languages, 16384 UTF-16 units per translation, conservative 8 MiB/file and shared 512 MiB retention. Original intent and both candidates survive upload release/restart; reopen recomputes files and refuses changed records. Download with artifact_read, then supply candidates to independent component review. No native import, existing-file rewriting, formatted/system text-list editing, project language activation, ownership/consumer/preservation or native qualification claim.")]
    public CallToolResult AuthorTextLists(string? uploadRef = null, string? recordId = null) => Run(store => store.AuthorTextLists(uploadRef, recordId));

    [McpServerTool(Name = "hmi_component_review", ReadOnly = false, Destructive = false, OpenWorld = false)]
    [Description("Review a committed hmi-component-review-request.v1/v2/v3/v4/v5/v6/v7 upload against exact saved PLC component and HMI destination reviews. Compare explicit component/interface mappings, proposed HMI outputs and independent baseline/current/proposed files; report type changes, collisions, ownership and drift. v2 requires impactLimits and adds separate bounded incoming consumer paths for each saved component/destination snapshot; no cross-snapshot joins, invented bindings or complete-coverage claim. Retain originals across upload release/restart. v3 adds independent post-operation observations, compared by exact file bytes with the reviewed create/update/remove/retain intent. Missing, changed and unexpected files are reported; declared completeness never proves native effects. v4 adds explicit classic-screen-backcolor.v1 expectations derived from current files with exact owner/value checks; proposed and observed documents are independently checked, including all other XML content and the declaration. Unassessed files remain visible. v5 adds explicit v21-full-fb-library-version.v1 associations between retained original exports and exact saved FB paths. Report type/version GUID agreement, contradictions, unavailable observations and unassociated selected components. Empty expectations allow association-only review. Expected effects and associations share the 64 MiB examined-XML budget. Identifier agreement grants no native identity, content, dependency or runtime qualification. v6 adds exact direct dependency indices and target paths within each selected saved scope, with optional original-export associations. Report missing mappings, duplicate references, conflicting type identities and cycles; no name joins or complete native closure. Bounds: 1000 entries per dependency observation, 20000 total references and 4096 explicit dependency mappings. v7 connects explicit dependency selections to exact same-scope saved consumers, supplied member bindings and existing output-effect checks. Original disagreement and incomplete evidence remain visible; a 1 MiB prefix limit records omitted association indices. No complete mapping or native impact is inferred. No scripts, native generation/writes or qualification bypass. Bounds: 4 MiB request, 256 outputs, 1024 mappings, 32 files at 16 MiB each/64 MiB total; per-snapshot traversal depth 1..5, paths 1..200, edge visits 1..20000, path bytes 1 MiB.")]
    public CallToolResult Review(string uploadRef) => Run(store => store.Review(uploadRef));

    [McpServerTool(Name = "hmi_component_review_page", ReadOnly = true, Destructive = false, OpenWorld = false)]
    [Description("Reopen an immutable component/HMI review by recordId. Revalidate request, all independent files and exact saved reviews. section: summary/components/outputs/bindings/files; v2 adds consumerPaths/consumerCoverage; v3 adds effectChecks; v4 adds derivedEffects/expectationCoverage; v5 adds libraryAssociations/libraryCoverage; v6 adds dependencyAssociations/dependencyCoverage/dependencyIdentities; v7 adds dependencyImpacts/dependencyImpactCoverage. Older records retain original results and reject newer sections. Nonnegative offset and 1..200 rows bounded to 128 KiB. Download original files/full report with artifact_read. No conflict-free report grants native write, preservation or regeneration acceptance.")]
    public CallToolResult Page(string recordId, string section = "summary", int offset = 0, int count = 50) => Run(store => store.Page(recordId, section, offset, count));
    private CallToolResult Run(Func<HmiComponentWorkflowStore, JsonObject> action)
    {
        object result; bool failed = false;
        try { result = action(new(options.ArtifactsDirectory)); }
        catch (Exception e) when (e is BridgeException or IOException or UnauthorizedAccessException or JsonException or ArgumentException or InvalidOperationException or System.Xml.XmlException)
        { failed = true; result = new { error = new { code = (e as BridgeException)?.Code ?? "HmiComponentReviewFailed", message = e.Message, nativeAccessAttempted = false } }; }
        string json = JsonSerializer.Serialize(result, BridgeProtocol.Json);
        return new() { IsError = failed, Content = [new TextContentBlock { Text = json }], StructuredContent = JsonSerializer.Deserialize<JsonElement>(json) };
    }
}
